<?php

declare(strict_types=1);
require dirname(__DIR__) . '/config/bootstrap.php';
use App\Auth;
use App\Database;
$userId=Auth::requireLogin();
$pdo=Database::connection();
$stmt=$pdo->prepare('SELECT name,email,balance FROM users WHERE id=:id');$stmt->execute([':id'=>$userId]);$user=$stmt->fetch();
$orderStmt=$pdo->prepare("SELECT COUNT(*) FROM orders WHERE user_id=:id");$orderStmt->execute([':id'=>$userId]);$orders=(int)$orderStmt->fetchColumn();
$activeStmt=$pdo->prepare("SELECT COUNT(*) FROM orders WHERE user_id=:id AND status NOT IN ('completed','partial','cancelled','failed','refunded')");$activeStmt->execute([':id'=>$userId]);$activeOrders=(int)$activeStmt->fetchColumn();
$recent=$pdo->prepare('SELECT o.id,o.status,o.quantity,o.remains,s.name service FROM orders o JOIN services s ON s.id=o.service_id WHERE o.user_id=:id ORDER BY o.id DESC LIMIT 5');$recent->execute([':id'=>$userId]);$recentOrders=$recent->fetchAll();
$currency=(string)env('CURRENCY','NGN');
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard | SMM Panel</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css" rel="stylesheet"></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container"><a class="navbar-brand fw-semibold" href="/dashboard.php">SMM Panel</a><div class="d-flex gap-2"><a class="btn btn-primary btn-sm" href="/order.php">New Order</a><a class="btn btn-outline-light btn-sm" href="/logout.php">Logout</a></div></div></nav><main class="container py-4 py-lg-5"><div class="mb-4"><div class="text-primary small fw-semibold text-uppercase">Customer dashboard</div><h1 class="h2 mb-1">Welcome, <?=htmlspecialchars($user['name'])?></h1><p class="text-muted mb-0"><?=htmlspecialchars($user['email'])?></p></div><div class="row g-3 mb-4"><div class="col-md-4"><div class="card border-0 shadow-sm h-100"><div class="card-body p-4"><div class="text-muted small">Wallet balance</div><h2 class="mb-3"><?=htmlspecialchars($currency)?> <?=number_format((float)$user['balance'],2)?></h2><a href="/wallet.php" class="btn btn-primary">Fund wallet</a></div></div></div><div class="col-md-4"><div class="card border-0 shadow-sm h-100"><div class="card-body p-4"><div class="text-muted small">Total orders</div><h2 class="mb-1"><?=$orders?></h2><div class="text-muted small mb-3"><?=$activeOrders?> currently active</div><a href="/orders.php" class="btn btn-outline-primary">Track orders</a></div></div></div><div class="col-md-4"><a href="/services.php" class="card border-0 shadow-sm h-100 text-decoration-none"><div class="card-body p-4"><div class="text-primary fs-3"><i class="bi bi-grid-3x3-gap"></i></div><h4 class="mt-2">Browse services</h4><p class="text-muted mb-0">Search the live catalogue and choose a service.</p></div></a></div></div><div class="card border-0 shadow-sm"><div class="card-header bg-white d-flex justify-content-between align-items-center"><strong>Recent orders</strong><a href="/orders.php" class="small">View all</a></div><div class="list-group list-group-flush"><?php foreach($recentOrders as $o):?><a href="/orders.php" class="list-group-item list-group-item-action d-flex justify-content-between align-items-center"><div><strong>#<?= (int)$o['id']?></strong> · <?=htmlspecialchars($o['service'])?><div class="small text-muted">Quantity <?=number_format((int)$o['quantity'])?><?php if($o['remains']!==null):?> · <?=number_format((int)$o['remains'])?> remaining<?php endif;?></div></div><span class="badge text-bg-secondary"><?=htmlspecialchars(ucwords(str_replace('_',' ',$o['status'])))?></span></a><?php endforeach;if(!$recentOrders):?><div class="p-4 text-center text-muted">You have not placed an order yet. <a href="/services.php">Browse services</a>.</div><?php endif;?></div></div></main></body></html>
